-- 34 seats. No location appears in a chair title.
delete from chair_holder where chair_id in (select id from chair);
delete from chair;
insert into chair (code, title, level, reports_daily, sg_level, function_name, band, purpose, capability_track_id, source_ref)
select v.code, v.title, v.lvl, false, v.sg, v.fn, v.band, v.purpose, t.id, v.src from (values
('BRD','Board of Directors','board','SG7','Governance','Enterprise','Governs the company. Does not operate it.','Board Governance','ORGDOC!BRD'),
('MD','Managing Director','board','SG7','Executive','Enterprise','Runs the company through function heads. Still personally holds Business Development.','Enterprise Leadership','ORGDOC!MD'),
('OPS','National Head — Risk Operations','function','SG6','Operations','Function head','Owns national risk operations delivery — verification, FCU-RCU and investigation — across four regions. Owns the collection number. Does not own the receivables ledger or the audit of his own quality.','Operations Leadership','ORGDOC!OPS'),
('AVP','AVP — Operations & Growth','function','SG6','Operations','Function head','All four regions report here. Also holds the Business Excellence chair reporting to the MD.','Operations Leadership','ORGDOC!AVP'),
('RM','Regional Manager','region','SG5','Operations','Senior / regional','Owns the West region as a business. Maharashtra, Mumbai, Goa, Gujarat and Chhattisgarh.','Regional Management','ORGDOC!RM_W'),
('BM','Branch Manager','branch','SG3','Operations','Unit manager','Total accountability for the branch: business, people, books and brand.','Branch Management','ORGDOC!BM_P'),
('TL','Team Leaders','branch','SG2','Operations','Supervisor','Runs the daily processing floor. Field executives report to the Branch Manager, not here.','Team Supervision','ORGDOC!TL'),
('BO','Back Office / Processing Executives','executive','SG1','Operations','Executive','Processes cases, prepares the report and maintains the system record.','Back Office Processing','ORGDOC!BO'),
('CE','Branch Collection Executive','executive','SG1','Operations','Executive','Stage one of collection. Gets the bank''s local officer to certify completed cases and approve the invoice, so it can move to central release. Collection starts where the relationship is.','Credit & Collections','ORGDOC!CE_P'),
('BDE','Business Development Executive','executive','SG1','Operations','Executive','Grows the branch book locally. Business development is a branch KPI, not only a head-office function.','Business Development','ORGDOC!BDE_NO'),
('FE','Field Executives / Verifiers','executive','SG1','Operations','Executive','Executes field verification. The evidence pack this chair produces is the product the client buys.','Field Verification','ORGDOC!FE'),
('PA','Franchise Partner','branch','SG3','Operations','Unit manager','Independent franchise firms operating Crux-branded locations under a profit-sharing agreement. They are counterparties, not employees. Crux manages the firm, its performance and its claim — not the people inside it.','Business Development','ORGDOC!PA_W'),
('BZ','Business Manager','function','SG4','Operations','Functional manager','Runs South zone business — revenue, collections and branch performance — beneath the Regional Manager chair.','Branch Management','ORGDOC!BZ_S'),
('ADM','Administration & Facilities','branch','SG2','Operations','Supervisor','Offices, assets, travel and admin vendors across the network.','Administration','ORGDOC!ADM'),
('CCM','Credit & Collections','function','SG4','Finance','Functional manager','Owns the collection number end to end and runs it as two stages. Branch executives clear local certification at the bank''s own branch. Central executives then pursue release from the bank''s payables desk. One target, one ageing report, one method — two teams working different stages of the same rupee.','Credit & Collections','ORGDOC!CCM'),
('CCE','Central Collections Executives','executive','SG1','Finance','Executive','Stage two of collection. Once a branch has obtained local certification, this team pursues release from the client''s central payables desk.','Credit & Collections','ORGDOC!CCE'),
('FIN','Finance Head','function','SG6','Finance','Function head','Owns credit policy, the ledger and the financial truth. Sets the collection target that Operations delivers, and measures DSO independently of the function collecting the money.','Finance Leadership','ORGDOC!FIN'),
('ACC','Accounts','region','SG5','Finance','Senior / regional','Books, closing, statutory compliance and ledger integrity, including partner revenue-share settlement.','Accounting & Statutory','ORGDOC!ACC'),
('ACE','Accounts Executives','executive','SG1','Finance','Executive','Transaction processing, reconciliation and partner share computation.','Accounting & Statutory','ORGDOC!ACE'),
('FEX','Finance Executive','executive','SG1','Finance','Executive','Scope not yet defined. No KRA document exists for this chair.','Undefined — scope pending','ORGDOC!FEX'),
('GRC','Assurance, Risk & Compliance','function','SG6','Assurance & People','Function head','Independent assurance over everything the company delivers. Reports to the MD with a direct line to the Board so a finding cannot be filtered on its way up. HR has moved out to its own function.','Assurance & Compliance','ORGDOC!GRC'),
('LEG','Legal & Compliance','function','SG4','Assurance & People','Functional manager','Contracts, litigation and compliance, held externally today.','Assurance & Compliance','ORGDOC!LEG'),
('RISK','Risk & Business Continuity','function','SG4','Assurance & People','Functional manager','Keeps the risk register, runs issue management, and owns what happens when something goes badly wrong.','Assurance & Compliance','ORGDOC!RISK'),
('HRH','Head — Human Resources','function','SG6','Assurance & People','Function head','People as a function in its own right. Split out of the assurance chair because one person cannot hold assurance and HR at this scale and remain independent in either.','HR Operations','ORGDOC!HRH'),
('LND','Learning & Development','function','SG4','Assurance & People','Functional manager','Builds capability at the pace the expansion needs, and runs the internship programme.','HR Operations','ORGDOC!LND'),
('INT','Interns — project based','executive','SG1','Assurance & People','Executive','Project-based interns owned centrally, deployed to a branch or a function.','HR Operations','ORGDOC!INT'),
('HRE','HR Operations','executive','SG1','Assurance & People','Executive','Operational HR across the employee lifecycle.','HR Operations','ORGDOC!HRE'),
('BEX','Business Excellence & PMO','function','SG6','Business Excellence','Function head','New chair. Designs the operating system: process, projects, org design. Assurance verifies conformance to what this chair authors.','Business Excellence','ORGDOC!BEX'),
('TEC','Technology','region','SG5','Business Excellence','Senior / regional','Platform, product and information security.','Technology','ORGDOC!TEC'),
('ENG','Engineering & Platform','branch','SG3','Business Excellence','Unit manager','Builds and runs the platform.','Technology','ORGDOC!ENG'),
('MIS','MIS & Business Analytics','function','SG4','Business Excellence','Functional manager','One source of management truth. Consolidates every function into a single reporting standard.','MIS & Analytics','ORGDOC!MIS'),
('BD','Business Development','function','SG4','Commercial','Functional manager','New client acquisition and empanelment execution. The MD formally owns the function.','Business Development','ORGDOC!BD'),
('BID','Bids, Tenders & Contracts','function','SG4','Commercial','Functional manager','Bid and tender pipeline through to executed agreement.','Bids & Contracts','ORGDOC!BID'),
('CS','Company Secretary','function','SG4','Governance','Functional manager','Statutory and secretarial compliance. Administrative line to the MD, functional line to the Board.','Company Secretarial','ORGDOC!CS')
) v(code,title,lvl,sg,fn,band,purpose,track,src) join capability_track t on t.name = v.track;
update chair c set parent_id = p.id from (values
('MD','BRD'),
('OPS','MD'),
('AVP','OPS'),
('RM','AVP'),
('BM','RM'),
('TL','BM'),
('BO','TL'),
('CE','BM'),
('BDE','BM'),
('FE','BM'),
('PA','RM'),
('BZ','RM'),
('ADM','OPS'),
('CCM','OPS'),
('CCE','CCM'),
('FIN','MD'),
('ACC','FIN'),
('ACE','ACC'),
('FEX','FIN'),
('GRC','MD'),
('LEG','GRC'),
('RISK','GRC'),
('HRH','MD'),
('LND','HRH'),
('INT','LND'),
('HRE','HRH'),
('BEX','MD'),
('TEC','BEX'),
('ENG','TEC'),
('MIS','BEX'),
('BD','MD'),
('BID','BD'),
('CS','MD')
) v(code,parent) join chair p on p.code = v.parent where c.code = v.code;
